package com.shrija.compliance.controller; import com.shrija.compliance.dto.*; import com.shrija.compliance.service.ComplianceConversationService; import jakarta.validation.Valid; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/compliance") public class ComplianceController { private final ComplianceConversationService service; public ComplianceController(ComplianceConversationService service){this.service=service;} @PostMapping("/chat") public ResponseEntity<ComplianceChatResponse> chat(@Valid @RequestBody ComplianceChatRequest r){var x=service.converse(r);return ResponseEntity.ok(new ComplianceChatResponse(x.sessionId(),x.responseText()));} }
